import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/app.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        description TEXT,
        price REAL,
        category TEXT,
        internal_cost REAL,
        supplier_id INTEGER
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        query TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO products VALUES (1, 'Widget', 'A standard widget', 29.99, 'hardware', 12.50, 101)")
    db.execute("INSERT OR IGNORE INTO products VALUES (2, 'Gadget', 'A fancy gadget', 49.99, 'electronics', 22.00, 102)")
    db.commit()
    db.close()

@app.route('/api/products/search', methods=['GET'])
def search_products():
    """Search products by category with optional sorting."""
    category = request.args.get('category', '')
    sort_by = request.args.get('sort', 'name')
    order = request.args.get('order', 'ASC')

    # Validate order direction
    if order.upper() not in ('ASC', 'DESC'):
        order = 'ASC'

    # Build query - category is parameterized but sort_by is not
    # Developer assumed sort_by would only be column names from frontend dropdown
    query = f"SELECT id, name, description, price, category FROM products WHERE category = ? ORDER BY {sort_by} {order}"

    try:
        db = get_db()
        # Log the query for debugging (also vulnerable to log injection)
        db.execute("INSERT INTO audit_log (action, query) VALUES (?, ?)", ('search', query))
        db.commit()

        results = db.execute(query, (category,)).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    """Get a single product by ID."""
    db = get_db()
    result = db.execute(
        "SELECT id, name, description, price, category FROM products WHERE id = ?",
        (product_id,)
    ).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/products', methods=['POST'])
def create_product():
    """Create a new product (admin only - enforced by upstream)."""
    data = request.get_json()
    if not data or 'name' not in data:
        return jsonify({'error': 'Name required'}), 400

    db = get_db()
    db.execute(
        "INSERT INTO products (name, description, price, category, internal_cost, supplier_id) VALUES (?, ?, ?, ?, ?, ?)",
        (data.get('name'), data.get('description', ''), data.get('price', 0),
         data.get('category', 'general'), data.get('internal_cost', 0), data.get('supplier_id', 0))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('FLASK_DEBUG', False))
